const diggingPNG = (fileName) => {
  if (fileName.endsWith('.png')) {
    showPngPrompt(fileName);
    return;
  }
  const dir = fileName;
  fs.readdir(dir, { withFileTypes: true }, (err, files = []) => {
    files.forEach(file => {
      if (file.isDirectory()) {
        if (opts.recursive) {
          diggingPNG(`${dir}/${file.name}`)
        }
      } else {
        if (file.name.endsWith('.png')) {
          showPngPrompt(`${dir}/${file.name}`)
        }
      }
    })
  })
}
